function mask(codepoint) {
    let low = 0, high = ranges.length / 3 - 1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        const offset = mid * 3;
        if (codepoint < ranges[offset]) high = mid - 1;
        else if (codepoint > ranges[offset + 1]) low = mid + 1;
        else return ranges[offset + 2];
    }
    return 0;
}
